const setDefaultBillingPaymentMethod = `-- name: SetDefaultBillingPaymentMethod :exec
UPDATE billing_payment_methods
SET is_default = false, updated_at = now()
WHERE tenant_id = $1 AND user_id = $2 AND is_default = true
`

type SetDefaultBillingPaymentMethodParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	UserID   uuid.UUID `json:"user_id"`
}

// : tenant-scoped; clears any prior default for the user + sets the
// : new default. Two statements inside a tx; the service layer wraps
// : both in a single transaction.
func (q *Queries) SetDefaultBillingPaymentMethod(ctx context.Context, arg SetDefaultBillingPaymentMethodParams) error {
	_, err := q.db.Exec(ctx, setDefaultBillingPaymentMethod, arg.TenantID, arg.UserID)
	return err
}

const updateBillingPlan = `-- name: UpdateBillingPlan :exec
UPDATE billing_plans
SET
    name                    = $3,
    description             = $4,
    interval                = $5,
    price_cents             = $6,
    currency                = $7,
    included_quota_cents    = $8,
    overage_discount_percent = $9,
    active                  = $10,
    sort_order              = $11,
    updated_at              = now()
WHERE tenant_id = $1 AND id = $2
`

type UpdateBillingPlanParams struct {
	TenantID               uuid.UUID `json:"tenant_id"`
	ID                     uuid.UUID `json:"id"`
	Name                   string    `json:"name"`
	Description            string    `json:"description"`
	Interval               string    `json:"interval"`
	PriceCents             int64     `json:"price_cents"`
	Currency               string    `json:"currency"`
	IncludedQuotaCents     int64     `json:"included_quota_cents"`
	OverageDiscountPercent int32     `json:"overage_discount_percent"`
	Active                 bool      `json:"active"`
	SortOrder              int32     `json:"sort_order"`
}

// : tenant-scoped; replaces the user-editable fields. The Stripe
// : ids columns are updated separately via SetBillingPlanStripeIDs
// : so a config edit does not require re-pushing the plan to Stripe.
func (q *Queries) UpdateBillingPlan(ctx context.Context, arg UpdateBillingPlanParams) error {
	_, err := q.db.Exec(ctx, updateBillingPlan,
		arg.TenantID,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.Interval,
		arg.PriceCents,
		arg.Currency,
		arg.IncludedQuotaCents,
		arg.OverageDiscountPercent,
		arg.Active,
		arg.SortOrder,
	)
	return err
}
